sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var requestBody = request.body.nextEntry();
    var email = requestBody.email;
    var firstName = requestBody.first_name;
    var lastName = requestBody.last_name;

    if (!email) {
        return new sn_ws_err.BadRequestError("Email is required.");
    }

    var grUserCheck = new GlideRecord('sys_user');
    if (grUserCheck.get('email', email)) {
        return new sn_ws_err.ConflictError("A user with this email already exists.");
    }

    // 1. Create User
    var grUser = new GlideRecord('sys_user');
    grUser.initialize();
    grUser.user_name = email;
    grUser.email = email;
    grUser.first_name = firstName;
    grUser.last_name = lastName;

    var userSysId = grUser.insert();

    if (userSysId) {
        // 2. Force inactive and locked status
        var grUpdate = new GlideRecord('sys_user');
        if (grUpdate.get(userSysId)) {
            grUpdate.active = false;
            grUpdate.locked_out = true;
            grUpdate.update();
        }

        // 3. ADD USER TO PORTAL GROUP WITH SNC_EXTERNAL ROLE
        var grGroupMember = new GlideRecord('sys_user_grmember');
        grGroupMember.initialize();
        grGroupMember.user = userSysId;
        grGroupMember.group = '7fca346e471e831089b4a22f316d437a'; // Group sys_id
        grGroupMember.insert();

        // 4. Trigger Verification Email Event
        gs.eventQueue('x_travel_buddy_app.custom.traveler.password_reset', grUser, userSysId, email);

        response.setBody({
            status: "success",
            message: "User registered and added to portal group successfully.",
            sys_id: userSysId
        });
        response.setStatus(201);
    } else {
        return new sn_ws_err.ServerError("Failed to create user record.");
    }

})(request, response);
